/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - Vpotula
/// Service class to send customer statements for AMEX.
/// </summary>
class METAMEXCustStmtSendService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// Sends customer statements per company and per customer.
    /// </summary>
    /// <param name = "_contract"><c>METAMEXCustStmtSendContract</c></param>
    private void sendStatements(METAMEXCustStmtSendContract _contract)
    {
        LedgerJournalTrans                      journalTrans;
        DimensionAttributeValueCombination      dimensionAttribute;

        while select Company, LedgerDimension, JournalNum from journalTrans
            group by JournalNum,PaymMode, Company, LedgerDimension
            where journalTrans.JournalNum == _contract.parmJournalNum()
        {
            select firstonly DisplayValue from dimensionAttribute
                where dimensionAttribute.RecId == journalTrans.LedgerDimension;
            this.sendEmailPerCust(dimensionAttribute.DisplayValue,
                                _contract.parmFromDate(),
                                _contract.parmToDate(),
                                journalTrans.JournalNum,
                                journalTrans.PaymMode,
                                journalTrans.company);
        }
    }

    /// <summary>
    /// Runs the customer statement report with criteria as per parms.Open transactions only
    /// Customer print management settings are used.
    /// </summary>
    /// <param name = "_custAccount">Customer account.</param>
    /// <param name = "_fromDate">statement from date.</param>
    /// <param name = "_toDate">statement to date.</param>
    /// <param name = "_journalId">Journal number.</param>
    /// <param name = "_paymMode">Method of payment.</param>
    /// <param name = "_company">Statement company</param>
    private void sendEmailPerCust(CustAccount _custAccount,
                                    FromDate    _fromDate,
                                    ToDate      _toDate,
                                    JournalId   _journalId,
                                    CustPaymMode _paymMode,
                                    str         _company)
    {
        METAMEXCustAccountStmtExtController     reportController  = new METAMEXCustAccountStmtExtController();
        CustAccountStatementExtContract         reportContract;

        Args    reportArgs = new Args();
        reportArgs.record(CustTable::find(_custAccount));

        reportController.metInitParms(reportArgs);

        reportContract = reportController.parmReportContract().parmRdpContract();
        reportContract.parmFromDate(_fromDate);
        reportContract.parmToDate(_toDate);
        reportContract.parmOnlyOpen(true); //Open transactions only
        reportContract.parmUsePrintManagement(true);
        reportController.parmMETSelectedCompany(_company);
        reportController.parmMETJournalId(_journalId);
        reportController.parmMETPaymMode(_paymMode);
        reportController.metUpdateBaseQuery(reportController.parmReportContract().parmQueryContracts().lookup(reportController.getFirstQueryContractKey()),
                                        _custAccount);
        reportController.parmLoadFromSysLastValue(false);
        reportController.run();
    }
